fn tuple_elements_resolve_whether_plain_labelled_or_optional() {
    let output = extract_one(&[(
        "Box.tsx",
        "type Tone = 'a' | 'b';\n\
         export function Box(props: { plain: [Tone, number]; labelled: [tone: Tone, count?: number] }) { return null; }\n",
