    let props = &output.components["Box"].props;
    let tone = PropType::LiteralUnion { members: vec!["a".into(), "b".into()], has_default: false };
    assert_eq!(props["plain"].prop_type, PropType::Tuple(vec![tone.clone(), PropType::Number]));
