// Generates small TypeScript programs over a grammar of aliases, interfaces and generic components whose names collide.
// usage: node gen.mjs <outDir> <count> <seed>
import fs from 'node:fs';
import path from 'node:path';

const [outDir, countArg, seedArg] = process.argv.slice(2);
const count = Number(countArg);
let state = Number(seedArg) >>> 0 || 1;
const rnd = () => {
  state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
  return state / 2 ** 32;
};
const pick = (xs) => xs[Math.floor(rnd() * xs.length)];
const chance = (p) => rnd() < p;

const NAMES = ['Value', 'T', 'A', 'P', 'K'];
const PARAM_NAMES = ['Value', 'T', 'A', 'P', 'K'];
const CONCRETE = ['number', "'outer'", 'string', 'boolean', '{ v: number }', 'string[]', '[number, string]', '42', 'null'];

function genProgram(index) {
  // module-level declarations: name -> { kind, params, ... }
  const decls = [];
  const taken = new Set();
  const fresh = () => {
    const free = NAMES.filter((n) => !taken.has(n));
    if (!free.length) return null;
    const n = pick(free);
    taken.add(n);
    return n;
  };
  const nDecl = 2 + Math.floor(rnd() * 4);
  for (let i = 0; i < nDecl; i++) {
    const name = fresh();
    if (!name) break;
    const kind = pick(['alias', 'alias', 'galias', 'iface', 'giface', 'galias']);
    if (kind === 'alias') decls.push({ name, kind, body: pick(CONCRETE) });
    else if (kind === 'iface') decls.push({ name, kind, member: pick(CONCRETE) });
    else {
      const x = pick(PARAM_NAMES);
      if (kind === 'galias') {
        const body = pick([`${x}`, `${x}[]`, `{ v: ${x} }`, `${x} | null`, `[${x}, number]`, `{ w: ${x}; n: number }`]);
        decls.push({ name, kind, param: x, body });
      } else {
        decls.push({ name, kind, param: x, optionalOther: chance(0.5) });
      }
    }
  }
  // a Read-style alias with a constraint, and a Cell interface, kept under fixed distinct names when free
  const extra = [];
  if (chance(0.5)) extra.push('type Read<X extends { v: unknown }> = X[\'v\'];');
  if (chance(0.5)) extra.push('interface Cell<X> { value: X }');
  const hasRead = extra.some((e) => e.startsWith('type Read'));
  const hasCell = extra.some((e) => e.startsWith('interface Cell'));

  const plain = decls.filter((d) => d.kind === 'alias' || d.kind === 'iface');
  const generic = decls.filter((d) => d.kind === 'galias' || d.kind === 'giface');

