    if (d.kind === 'alias') lines.push(`type ${d.name} = ${d.body};`);
    else if (d.kind === 'iface') lines.push(`interface ${d.name} { value: ${d.member}; }`);
    else if (d.kind === 'galias') lines.push(`type ${d.name}<${d.param}> = ${d.body};`);
    else lines.push(`interface ${d.name}<${d.param}> { value: ${d.param};${d.optionalOther ? ' other?: number;' : ''} }`);
  }
  lines.push(...extra);

