    else if (mode === 'alias') {
      pre = `type CProps${c} = ${body};`;
      propsType = `CProps${c}`;
    } else {
      pre = `interface CProps${c} ${body.replace(/;\s*}$/, ' }').replace(/(\{ )/, '{ ')}`;
      pre = `interface CProps${c} { ${members.join('; ')}; }`;
      propsType = `CProps${c}`;
