    const usesTp = tps.some((t) => new RegExp(`\\b${t}\\b`).test(members.join(';'))) && mode !== 'inline';
    if (usesTp) {
      comps.push({ pre: '', name: `C${index}_${c}`, tps, propsType: body });
    } else {
      comps.push({ pre, name: `C${index}_${c}`, tps, propsType });
    }
  }
  for (const c of comps) {
    if (c.pre) lines.push(c.pre);
    lines.push(`export function ${c.name}${c.tps.length ? `<${c.tps.join(', ')}>` : ''}(p: ${c.propsType}) { return null; }`);
  }
  return lines.join('\n') + '\n';
}

