  if (f & ts.TypeFlags.Unknown) return 'unknown';
  if (f & ts.TypeFlags.Void) return 'void';
  if (f & ts.TypeFlags.TypeParameter) return t.symbol.name;
  if (f & ts.TypeFlags.Union) return unionOf(t.types.map((x) => tsNorm(x, depth + 1)));
  if (f & ts.TypeFlags.Intersection) return uniqSorted(t.types.map((x) => wrap(tsNorm(x, depth + 1)))).join(' & ');
  if (f & ts.TypeFlags.IndexedAccess || f & ts.TypeFlags.Conditional || f & ts.TypeFlags.Index) return '?' + checker.typeToString(t);
  if (f & ts.TypeFlags.Object) {
    if (checker.isArrayType(t)) return wrap(tsNorm(checker.getTypeArguments(t)[0], depth + 1)) + '[]';
    if (checker.isTupleType(t)) {
      return '[' + checker.getTypeArguments(t).map((x, i) => {
        const opt = t.target.elementFlags?.[i] & ts.ElementFlags.Optional;
        return opt ? tsNorm(x, depth + 1) + '?' : tsNorm(x, depth + 1);
      }).join(', ') + ']';
    }
    const sym = t.symbol;
    // a named interface stays by name, as caliper keeps it
    if (sym && sym.flags & ts.SymbolFlags.Interface && !(sym.flags & ts.SymbolFlags.TypeLiteral)) {
      const args = (t.objectFlags & ts.ObjectFlags.Reference) ? checker.getTypeArguments(t) : [];
      const own = sym.declarations?.[0]?.typeParameters?.length ?? 0;
      return args.length ? `${sym.name}<${args.slice(0, own).map((x) => tsNorm(x, depth + 1)).join(', ')}>` : sym.name;
    }
    const sigs = checker.getSignaturesOfType(t, ts.SignatureKind.Call);
    if (sigs.length === 1) {
      const s = sigs[0];
      const params = s.getParameters().map((p) => tsNorm(checker.getTypeOfSymbolAtLocation(p, p.valueDeclaration), depth + 1));
      return `(${params.join(', ')}) => ${tsNorm(s.getReturnType(), depth + 1)}`;
    }
    const props = checker.getPropertiesOfType(t).map((p) => {
      const decl = p.valueDeclaration ?? p.declarations?.[0];
      const pt = checker.getTypeOfSymbolAtLocation(p, decl);
      const optional = !!(p.flags & ts.SymbolFlags.Optional);
      return `${p.name}${optional ? '?' : ''}: ${show(optional ? stripUndef(tsNorm(pt, depth + 1)) : tsNorm(pt, depth + 1))}`;
    });
    return props.length ? `{ ${props.sort().join('; ')} }` : '{}';
  }
  return '?' + checker.typeToString(t);
}

// ── caliper side ──
function calNorm(t) {
  switch (t.kind) {
    case 'string': case 'number': case 'boolean': case 'null': case 'undefined': case 'any': case 'never': case 'unknown': case 'void':
      return t.kind;
    case 'stringLiteral': return JSON.stringify(t.value);
    case 'numberLiteral': return String(t.value);
    case 'boolLiteral': return String(t.value);
    case 'literalUnion': return unionOf(t.members.map((m) => JSON.stringify(m)));
    case 'union': return unionOf(t.members.map(calNorm));
    case 'intersection': return uniqSorted(t.members.map((m) => wrap(calNorm(m)))).join(' & ');
    case 'array': return wrap(calNorm(t.element)) + '[]';
    case 'readonly': return calNorm(t.element);
    case 'tuple': return '[' + t.elements.map(calNorm).join(', ') + ']';
    case 'object': {
      const fields = t.fields.map((f) => `${f.name}${f.required === false ? '?' : ''}: ${show(f.required === false ? stripUndef(calNorm(f.propType)) : calNorm(f.propType))}`);
      return fields.length ? `{ ${fields.sort().join('; ')} }` : '{}';
    }
    case 'named': return t.args.length ? `${t.name}<${t.args.map((a) => show(calNorm(a))).join(', ')}>` : t.name;
    case 'function': return `(${t.params.map((p) => show(calNorm(p.type))).join(', ')}) => ${show(calNorm(t.returnType))}`;
    case 'opaque': return '?' + t.raw;
    default: return '?' + t.kind;
  }
}

// ── collect ──
const expected = new Map(); // component -> Map(prop -> {type, optional})
const tsErrors = [];
for (const sf of program.getSourceFiles()) {
  if (!files.includes(sf.fileName)) continue;
  for (const d of ts.getPreEmitDiagnostics(program, sf)) tsErrors.push(`${path.basename(sf.fileName)}: ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`);
  ts.forEachChild(sf, (node) => {
    if (!ts.isFunctionDeclaration(node) || !node.name) return;
    const param = node.parameters[0];
    const pt = checker.getTypeAtLocation(param);
    const props = new Map();
    for (const p of checker.getPropertiesOfType(pt)) {
      const decl = p.valueDeclaration ?? p.declarations?.[0];
      const optional = !!(p.flags & ts.SymbolFlags.Optional);
      let n = tsNorm(checker.getTypeOfSymbolAtLocation(p, decl));
      if (optional) n = stripUndef(n);
      props.set(p.name, { type: show(n), optional, file: path.basename(sf.fileName) });
