  });
}
const badFiles = new Set(tsErrors.map((e) => e.split(':')[0]));

const out = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
let compared = 0;
const mismatches = [];
const skipped = [];
for (const [name, props] of expected) {
  const file = [...props.values()][0]?.file ?? '';
  const comp = out.components[name];
  if (!comp) { skipped.push(`${name}: not found by caliper`); continue; }
  const got = new Map();
  for (const id of comp.props) {
    const p = out.props[id];
    let n = calNorm(p.type);
    if (!p.required) n = stripUndef(n);
    got.set(p.name, { type: show(n), optional: !p.required });
  }
  for (const [pn, exp] of props) {
    compared++;
    const g = got.get(pn);
    if (!g) { mismatches.push({ name, prop: pn, exp: exp.type, got: '(missing)', file: exp.file, cls: 'missing' }); continue; }
    if (g.type !== exp.type || g.optional !== exp.optional) {
      mismatches.push({ name, prop: pn, exp: exp.type + (exp.optional ? ' (optional)' : ''), got: g.type + (g.optional ? ' (optional)' : ''), file: exp.file });
    }
  }
}
const diags = (out.diagnostics ?? []).filter((d) => d.severity !== 'info');
console.log(JSON.stringify({ programFiles: files.length, tsErrorFiles: [...badFiles], compared, mismatches, skipped, caliperDiagnostics: diags.map((d) => `${d.severity}: ${d.message}`) }, null, 1));

